import{_ as n,o as i,c as t,ae as r}from"./chunks/framework.BvHJbMD4.js";const c=JSON.parse('{"title":"Drehbuch-Update: Szene 22 - Die Emoji-Lektion\\\\n\\\\nSTIL: Eine traumartige Sequenz, in der sich die Zeiten vermischen. Schwarz-Weiß-Ästhetik trifft auf moderne Smartphone-Beleuchtung.\\\\n\\\\nBESETZUNG:\\\\n- Helmut Horten: August Diehl\\\\n- Der junge Sekretär (Schmid-Typ): Ein nervöser Schauspieler in einem viel zu engen Slim-Fit-Anzug.\\\\n\\\\n---\\\\n\\\\nINT. HORTENS ARBEITSZIMMER - NACHT\\\\n\\\\nHorten (Diehl) sitzt am Schreibtisch. Er hält einen Federhalter in der Hand. Vor ihm steht der junge Sekretär, der hektisch auf seinem Smartphone tippt.\\\\n\\\\nHORTEN\\\\n(ohne aufzusehen)\\\\nWoran arbeiten Sie da, mein Junge?\\\\n\\\\nSEKRETÄR\\\\n(begeistert)\\\\nIch schicke gerade eine Bestätigung für den Vorstandsposten der Staats-Holding raus, Herr Horten! Mit zwei Raketen-Emojis und einem Bizeps. Die Leute sollen wissen, dass wir Gas geben!\\\\n\\\\nHorten legt den Federhalter langsam ab. Das Geräusch schneidet durch den Raum.\\\\n\\\\nHORTEN\\\\nRaketen? Bizeps? Sie hinterlassen Fußabdrücke in einem Sumpf, aus dem Sie nie wieder herauskommen werden.\\\\n\\\\nSEKRETÄR\\\\nAber es ist verschlüsselt! Wir sind die Familie!\\\\n\\\\nHORTEN\\\\n(steht langsam auf, tritt ins Licht)\\\\nHören Sie mir gut zu. Ein Deal ist wie ein guter Wein: Er braucht Dunkelheit, Stille und... kein Protokoll. Wenn Sie ein Versprechen geben, geben Sie es mit einem Händedruck. Wenn Sie Macht ausüben, tun Sie es mit einem Blick. Aber niemals, hören Sie, niemals mit einem gelben, lachenden Gesichtchen in einer Cloud.\\\\n\\\\nEr tritt ganz nah an den Sekretär heran. Seine Stimme ist eiskalt.\\\\n\\\\nHORTEN\\\\nIn fünfzig Jahren wird man meine Konten suchen und nichts finden außer Legenden. Man wird Ihre Telefon-Clouds suchen und nichts finden außer... Peinlichkeiten.\\\\n\\\\nFADE TO BLACK.","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/szene-emoji-lektion.md","filePath":"logbuch/szene-emoji-lektion.md"}'),s={name:"logbuch/szene-emoji-lektion.md"};function a(h,e,u,d,m,l){return i(),t("div",null,[...e[0]||(e[0]=[r("",1)])])}const g=n(s,[["render",a]]);export{c as __pageData,g as default};
